import { mapGetters } from 'vuex'
import Detail from "./components/detail";
import ImportTable from './components/importTable'
import { securityList, securityDelete, allCategory } from "@/api/safeDanger/computerroom"

// import { list, del } from "@/api/safeDanger/computerroom";
export default {
  name: "index",
  computed: {
    ...mapGetters([
      'nickName',
      'companyId',
      'companyCode',
    ]),
  },
  components: {Detail, ImportTable},
  data() {
    return {
      importTableVisible: false,

      tableHeight:undefined,
      isEdit: false,
      isInfo: false,
      roomId: undefined,
      dialogTitle: '',
      dialogVisible: false,
      // 遮罩层
      loading: true,
      // 选中数组
      ids: [],
      // 选中数据
      multipleSelection: [],
      // 总条数
      total: 0,
      // 用户表格数据
      tableList: null,
      // 查询参数
      queryParams: {
        current: 1,
        size: 20,
        category: undefined,
        content: undefined,
        supervision: undefined,
        supervisionPoint: undefined
      },
      queryDisabled: {
        showDeviceType: true,
        showUnitSecond: false
      },

      supervisionList: []
    }
  },
  created() {

    this.getList();
  },
  mounted() {
    this.getCurrentHeight()
    window.addEventListener('resize', this.getCurrentHeight)
    window.addEventListener('webkitvisibilitychange', this.getCurrentHeight)
  },
  methods: {
    handleRow(row){
      this.roomId = row.id
      this.importTableVisible = true
    },
    initData(){
      allCategory().then(res=>{
        this.supervisionList = res.data
      })
    },
    // 获取自适应高度
    getCurrentHeight() {
      let windowHeight = window.innerHeight //窗口高度
      this.tableHeight = (windowHeight - 280) + 'px'
    },
    closeDialog(){
      this.dialogVisible = false
      this.importTableVisible = false
      this.getList();
    },
    getList() {
      this.initData()
      this.loading = true
      securityList(this.queryParams).then(response =>{
        this.tableList = response.data.records
        this.total = response.data.total
        this.loading = false
      })
    },
    handleSelectionChange(val) {
      this.ids = []
      this.multipleSelection = val;
      this.ids = val.map(item => item.id);
    },
    /** 搜索按钮操作 */
    handleQuery() {
      this.getList();
    },

    /** 重置按钮操作 */
    resetQuery() {
      this.$refs.queryForm.resetFields();
      this.handleQuery();
    },
    handleDelete() {
      const ids = this.ids;
      this.$confirm('是否确认删除选中数据项?', "警告", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(function() {
        return securityDelete(ids);
      }).then(rsp => {
        this.getList();
        this.$message.success('删除成功');
      }).catch(function() {});
    },
    handleAdd() {
      this.roomId = undefined
      this.dialogTitle = '新增'
      this.dialogVisible = true
      this.isEdit = false
      this.isInfo = false
    },
    handleUpdate() {
      if(this.multipleSelection.length<=0 || this.multipleSelection.length>1){
        this.$message({
          message: '请选择一条需要修改记录！',
          type: 'warning'
        });
        return;
      }
      this.roomId = this.multipleSelection[0].id;
      this.dialogTitle = '编辑';
      this.dialogVisible = true;
      this.isEdit = true
      this.isInfo = false
    },
    handleDblclick(row) {
      this.roomId = row.id;
      this.dialogTitle = '详情';
      this.dialogVisible = true;
      this.isEdit = true
      this.isInfo = true
    },
    handleClose() {
      this.dialogVisible = false
      this.getList();
    }
  }
}
